package com.taller.portal.config;
import com.taller.portal.model.Role; import com.taller.portal.model.RoleName; import com.taller.portal.model.User; import com.taller.portal.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder;
/** Carga roles y migra la cuenta técnica local al rol administrador. */
@Configuration public class DataInitializer { /** @return inicializador de catálogo y cuenta local. */ @Bean CommandLineRunner seed(RoleRepository roles,UserRepository users,PasswordEncoder e){return a->{ for(RoleName r:RoleName.values())roles.findByNombre(r).orElseGet(()->roles.save(new Role(r, switch(r){case DUENO->"Administración total";case MECANICO->"Órdenes de servicio";case CLIENTE->"Consulta de sus vehículos";case SECRETARIA->"Agenda y clientes";case DESARROLLADOR->"Gestión técnica y cuentas";case ADMINISTRADOR_SISTEMA->"Registro y administración del sistema";case RECEPCIONISTA->"Registro y atención de clientes";}))); User u=users.findByEmail("desarrollador@taller.local").orElseGet(()->{User n=new User();n.nombre="Administrador del sistema";n.email="desarrollador@taller.local";n.celular="0000000000";n.passwordHash=e.encode("DevTaller2026!");n.emailVerificado=true;return n;});u.rol=roles.findByNombre(RoleName.ADMINISTRADOR_SISTEMA).orElseThrow();users.save(u);};}}
